"""Semantic conventions for voice observability spans and metrics.

Single source of truth for every span name, span-event name, attribute key,
metric name, and metric attribute key emitted by the voice observability
helpers. Span names follow the ``{verb} {object}`` OTel naming guidance;
custom attributes use the ``voice.*`` / ``rasa.*`` / ``audio.*`` namespaces.

Privacy rule for everything defined here: content attributes are populated
only behind their explicit capture gates. Ungated attributes and event
payloads carry only bounded signals (ids, counts, durations, flags); DTMF
digit values and raw audio are never captured.
"""

TRACER_NAME = "rasa.voice"
METER_NAME = "rasa.voice"

# ---------------------------------------------------------------------------
# Span names
# ---------------------------------------------------------------------------

SPAN_NAME_VOICE_CALL = "voice call"
SPAN_NAME_CONNECT_ASR = "connect asr"
SPAN_NAME_CONNECT_TTS = "connect tts"
SPAN_NAME_DISCONNECT_ASR = "disconnect asr"
SPAN_NAME_DISCONNECT_TTS = "disconnect tts"
SPAN_NAME_TRANSCRIBE_AUDIO = "transcribe audio"
SPAN_NAME_HANDLE_BARGE_IN = "handle barge-in"
SPAN_NAME_HANDLE_DTMF = "handle dtmf"
SPAN_NAME_HANDLE_SILENCE = "handle silence"
SPAN_NAME_HANDLE_TURN = "handle turn"
SPAN_NAME_SYNTHESIZE_SPEECH = "synthesize speech"
SPAN_NAME_PLAY_AUDIO = "play audio"
SPAN_NAME_STORE_CALL_RECORDING = "store call recording"
# Created only when channel-message processing fails.
SPAN_NAME_PROCESS_CHANNEL_MESSAGE = "process channel message"
# Created only when composing a raw event through the handler graph fails.
SPAN_NAME_COMPOSE_EVENT = "compose event"

# ---------------------------------------------------------------------------
# Span-event names — call lifecycle (root span)
# ---------------------------------------------------------------------------

EVENT_CALL_STARTED = "voice.call_started"
# Emitted when active call processing hands over to teardown — not when the
# call is fully torn down. Engine disconnects and the websocket close run
# after this event, still inside the root span; that tail is covered by the
# `disconnect asr` / `disconnect tts` spans.
EVENT_CALL_ENDED = "voice.call_ended"
EVENT_DISCONNECT = "voice.disconnect"
# Emitted when the agent *requests* a hangup (deferred until the goodbye
# audio drains); execution appears later as `voice.disconnect` +
# `voice.call_ended`.
EVENT_HANGUP_REQUESTED = "voice.hangup_requested"

# ---------------------------------------------------------------------------
# Span-event names — event composition
# ---------------------------------------------------------------------------

EVENT_COMPOSITION_ERROR = "voice.composition_error"
EVENT_TURN_EVENT_ENQUEUED = "voice.turn_event_enqueued"
# A gated transcript entered barge-in classification; the verdict (accepted
# or ignored) follows as its own event.
EVENT_BARGE_IN_ATTEMPTED = "voice.barge_in_attempted"
EVENT_BARGE_IN_ACCEPTED = "voice.barge_in_accepted"
EVENT_BARGE_IN_IGNORED = "voice.barge_in_ignored"
EVENT_BARGE_IN_FAILED = "voice.barge_in_failed"
EVENT_DTMF_STARTED = "voice.dtmf_started"
EVENT_DTMF_DIGIT = "voice.dtmf_digit"
EVENT_DTMF_ACCEPTED = "voice.dtmf_accepted"
EVENT_DTMF_IGNORED = "voice.dtmf_ignored"
EVENT_DTMF_TIMEOUT = "voice.dtmf_timeout"
EVENT_SILENCE_DETECTED = "voice.silence_detected"
EVENT_SILENCE_ACCEPTED = "voice.silence_accepted"

# ---------------------------------------------------------------------------
# Span-event names — input processing
# ---------------------------------------------------------------------------

EVENT_TRANSCRIPT_REJECTED = "voice.transcript_rejected"

# ---------------------------------------------------------------------------
# Span-event names — filler / acknowledgement messages
# ---------------------------------------------------------------------------

EVENT_FILLER_SENT = "voice.filler_sent"
# Emitted when cancellation skips committing a generated agent message.
EVENT_RESPONSE_DROPPED = "rasa.turn.response_dropped"

# ---------------------------------------------------------------------------
