EVENT_TTS_COMPLETE = "voice.tts_complete"
EVENT_TTS_ERROR = "voice.tts_error"
EVENT_PLAYBACK_START = "voice.playback_start"
EVENT_PLAYBACK_FINISHED = "voice.playback_finished"
EVENT_PLAYBACK_CANCELLED = "voice.playback_cancelled"
