# Composer / queue attributes
# ---------------------------------------------------------------------------

SIGNAL_HANDLER = "signal.handler"
# Class name of the turn event flowing through the composer (e.g.
# `UserDTMFInput`) — namespaced to avoid clashing with OTel's generic
