VOICE_TURN_EVENT_TYPE = "voice.turn_event.type"
PARTIAL_TRANSCRIPT_COUNT = "partial_transcript.count"

# ---------------------------------------------------------------------------
# Error attributes
# ---------------------------------------------------------------------------

# Stable, low-cardinality failure class (the exception type name) stamped on
# every span that sets ERROR status, so failure-rate-by-type dashboards need
# not match free-text exception messages.
ERROR_TYPE = "error.type"

# ---------------------------------------------------------------------------
# Metric names (OTel Metrics API) — exported whenever a `metrics:` endpoint
# is configured, independently of tracing
# ---------------------------------------------------------------------------

# Histogram (seconds): total call duration, recorded once per call.
METRIC_VOICE_CALL_DURATION = "rasa.voice.call.duration"
# Histogram (seconds): synthesis request to first generated audio chunk.
METRIC_VOICE_TTS_TIME_TO_FIRST_AUDIO = "rasa.voice.tts.time_to_first_audio"
# Histogram (seconds): synthesis request to the utterance's terminal state.
METRIC_VOICE_TTS_SYNTHESIS_DURATION = "rasa.voice.tts.synthesis.duration"
# Histogram (seconds): first delivered chunk to the playback's terminal state.
METRIC_VOICE_PLAYBACK_DURATION = "rasa.voice.playback.duration"
# Counter: unexpected operational failures (never behavioral decisions).
METRIC_VOICE_OPERATION_FAILURES = "rasa.voice.operation.failures"
# Counter: evaluated barge-in decisions, by outcome and reason.
METRIC_VOICE_BARGE_IN_DECISIONS = "rasa.voice.barge_in.decisions"
# Counter: evaluated DTMF decisions, by outcome.
METRIC_VOICE_DTMF_DECISIONS = "rasa.voice.dtmf.decisions"
# Counter: fired silence timeouts, by outcome and configured timeout.
METRIC_VOICE_SILENCE_TIMEOUTS = "rasa.voice.silence_timeouts"
# Counter: audio throughput in bytes, by direction.
METRIC_VOICE_AUDIO_BYTES = "rasa.voice.audio.bytes"

# ---------------------------------------------------------------------------
# Metric attribute keys — every value is a short developer-controlled token
# (an enum from rasa.tracing.voice.metrics, an engine name, an exception
# type name, a boolean, or a numeric configuration value). IDs, content,
# model names, URLs, and exception messages are never metric attributes;
# SDK Views enforce per-instrument allowlists on top.
# ---------------------------------------------------------------------------

METRIC_ATTR_COMPONENT = "rasa.voice.component"
METRIC_ATTR_OPERATION = "rasa.voice.operation"
METRIC_ATTR_PROVIDER = "rasa.voice.provider"
METRIC_ATTR_OUTCOME = "rasa.voice.outcome"
METRIC_ATTR_REASON = "rasa.voice.reason"
# Exception class name (never the message).
METRIC_ATTR_ERROR_TYPE = "rasa.voice.error_type"
METRIC_ATTR_AUDIO_DIRECTION = "rasa.voice.audio.direction"
METRIC_ATTR_TTS_CACHE_HIT = "rasa.voice.tts.cache_hit"
# Configured silence timeout (a config value, not a runtime measurement).
METRIC_ATTR_SILENCE_TIMEOUT_S = "rasa.voice.silence.timeout_s"
